export interface LearningConceptRef {
  id: string;
  role: string;
}

export interface LearningConceptStage {
  label: string;
  relation: string;
  concepts: readonly string[];
}

export interface PaperReading {
  title: string;
  href: string;
  problem: string;
  contribution: string;
  assumptions: string;
  evidenceScope: string;
  notClaim: string;
  sectionId?: string;
  internalHref?: string;
}

export function getPaperReadingInternalHref(paper: PaperReading): string {
  if (paper.internalHref) return paper.internalHref;
  if (paper.sectionId) return `#${paper.sectionId}`;
  throw new Error(`논문 해설 경로가 없습니다: ${paper.title}`);
}

export type ExerciseLevel = "basic" | "advanced";

export interface ArticleExercise {
  level: ExerciseLevel;
  question: string;
  answerChecklist: readonly string[];
  requiredConcepts: readonly string[];
  sectionId: string;
}

export interface ConceptExplanationContract {
  id: string;
  sectionId: string;
  intuition: string;
  workedExample: string;
  boundary: string;
  proofIdea?: string;
  counterexample?: string;
  scientificGrounding?: {
    observable: string;
    unitsAndDimensions: string;
    modelAssumptions: string;
    measurementExample: string;
    invalidConditions: string;
    referenceFrame?: string;
  };
}

export interface ArticleLearningContract {
  coreIdea: string;
  entryLevel?: boolean;
  entryNote?: string;
  assumedKnowledge: readonly LearningConceptRef[];
  introducedHere: readonly LearningConceptRef[];
  conceptExplanations: readonly ConceptExplanationContract[];
  conceptStages: readonly LearningConceptStage[];
  exercises: readonly ArticleExercise[];
  papers?: readonly PaperReading[];
}

